def decode_runs(text: str) -> str:
    """Decode runs of decimal count followed by lowercase ASCII letter."""
    if text == "":
        return ""
    i = 0
    n = len(text)
    result = []
    while i < n:
        # Each run must start with a digit
        if not text[i].isdigit():
            raise ValueError("Invalid input: expected digit")
        # Parse the count
        start = i
        while i < n and text[i].isdigit():
            i += 1
        count_str = text[start:i]
        count = int(count_str)
        if count <= 0:
            raise ValueError("Zero count not allowed")
        # After digits, there must be a lowercase ASCII letter
        if i >= n:
            raise ValueError("Missing letter after count")
        letter = text[i]
        if not ('a' <= letter <= 'z'):
            raise ValueError("Invalid letter: must be lowercase ASCII")
        result.append(letter * count)
        i += 1  # move past the letter
    return "".join(result)

def flatten(value):
    """
    Recursively flatten lists and tuples into a new list.
    All other values, including strings and dictionaries, are atomic.
    """
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import copy
def deep_merge(left, right):
    """
    Recursively merge two dictionaries.
    - If a key exists in both and both values are dicts, merge them recursively.
    - Otherwise, the value from `right` replaces the value from `left`.
    - The function does not mutate the input dictionaries.
    - The returned dictionary contains independent copies of mutable values.
    """
    result = {}
    all_keys = set(left.keys()) | set(right.keys())
    for key in all_keys:
        lval = left.get(key)
        rval = right.get(key)
        if key in left and key in right:
            if isinstance(lval, dict) and isinstance(rval, dict):
                result[key] = deep_merge(lval, rval)
            else:
                result[key] = copy.deepcopy(rval)
        elif key in left:
            result[key] = copy.deepcopy(lval)
        else:
            result[key] = copy.deepcopy(rval)
    return result

def json_pointer(value, pointer):
    """
    Resolve a JSON Pointer (RFC6901) into a value within a JSON-like structure.
    """
    if pointer == "":
        return value

    # Split pointer into tokens, handling leading slash
    parts = pointer.split('/')
    if parts and parts[0] == '':
        parts = parts[1:]
    tokens = parts

    current = value
    for token in tokens:
        # Decode JSON Pointer escape sequences (~0 -> ~, ~1 -> /) in that order
        decoded_parts = []
        i = 0
        while i < len(token):
            if token[i] == '~':
                if i + 1 >= len(token):
                    raise ValueError("Malformed escape: '~' at end of token")
                next_char = token[i + 1]
                if next_char == '1':
                    decoded_parts.append('/')
                    i += 2
                elif next_char == '0':
                    decoded_parts.append('~')
                    i += 2
                else:
                    raise ValueError(f"Malformed escape: '~{next_char}' in token")
            else:
                decoded_parts.append(token[i])
                i += 1
        token_decoded = ''.join(decoded_parts)

        if token_decoded == '':
            raise ValueError("Empty token in pointer")

        # Navigate according to the type of the current value
        if isinstance(current, dict):
            if token_decoded in current:
                current = current[token_decoded]
            else:
                raise ValueError(f"Key '{token_decoded}' not found")
        elif isinstance(current, list):
            # List indices must be canonical nonnegative decimal integers
            if not token_decoded.isdigit():
                raise ValueError(f"Invalid list index: '{token_decoded}'")
            if token_decoded != "0" and token_decoded.startswith('0'):
                raise ValueError(f"List index has leading zero: '{token_decoded}'")
            try:
                index = int(token_decoded)
            except ValueError:
                raise ValueError(f"Invalid list index: '{token_decoded}'")
            if index < 0:
                raise ValueError(f"List index must be nonnegative: '{token_decoded}'")
            if index >= len(current):
                raise ValueError(f"List index out of range: {index}")
            current = current[index]
        else:
            raise ValueError(f"Cannot resolve pointer into non-container type: {type(current)}")

    return current

def expression(text):
    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0

        def skip_whitespace(self):
            while self.pos < len(self.s) and self.s[self.pos].isspace():
                self.pos += 1

        def peek(self):
            self.skip_whitespace()
            if self.pos >= len(self.s):
                return ''
            return self.s[self.pos]

        def consume(self):
            ch = self.s[self.pos]
            self.pos += 1
            return ch

        def parse_number(self):
            self.skip_whitespace()
            if self.pos >= len(self.s) or not self.s[self.pos].isdigit():
                raise ValueError("Expected number")
            start = self.pos
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1
            return int(self.s[start:self.pos])

        def parse_factor(self):
            ch = self.peek()
            if ch == '+':
                self.consume()
                return +self.parse_factor()
            elif ch == '-':
                self.consume()
                return -self.parse_factor()
            elif ch == '(':
                self.consume()  # '('
                val = self.parse_expression()
                if self.peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                self.consume()  # ')'
                return val
            elif ch.isdigit():
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character '{ch}'")

        def parse_term(self):
            left = self.parse_factor()
            while True:
                ch = self.peek()
                if ch == '*':
                    self.consume()
                    right = self.parse_factor()
                    left = left * right
                else:
                    break
            return left

        def parse_expression(self):
            left = self.parse_term()
            while True:
                ch = self.peek()
                if ch == '+':
                    self.consume()
                    right = self.parse_term()
                    left = left + right
                elif ch == '-':
                    self.consume()
                    right = self.parse_term()
                    left = left - right
                else:
                    break
            return left

    parser = Parser(text)
    result = parser.parse_expression()
    parser.skip_whitespace()
    if parser.pos != len(parser.s):
        raise ValueError("Invalid syntax")
    return result

def glob_match(pattern, text):
    from functools import lru_cache

    @lru_cache(None)
    def match(p_idx, t_idx):
        if p_idx == len(pattern):
            return t_idx == len(text)
        p_char = pattern[p_idx]
        if p_char == '*':
            # match zero or more characters
            return match(p_idx + 1, t_idx) or (t_idx < len(text) and match(p_idx, t_idx + 1))
        if p_char == '?' or p_char == text[t_idx]:
            return match(p_idx + 1, t_idx + 1)
        return False

    return match(0, 0)

def memo_cycle(definitions, name):
    memo = {}
    stack = set()

    def compute(node):
        if node in memo:
            return memo[node]
        if node in stack:
            raise ValueError(f"Cycle detected involving {node}")
        stack.add(node)
        definition = definitions.get(node)
        if definition is None:
            raise ValueError(f"Missing dependency: {node}")
        if isinstance(definition, int):
            value = definition
        elif isinstance(definition, list):
            total = 0
            for dep in definition:
                total += compute(dep)
            value = total
        else:
            raise ValueError(f"Invalid definition for {node}")
        stack.remove(node)
        memo[node] = value
        return value

    return compute(name)
